#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Migration Runner
 * Reads SQL files from ./migrations/ directory and logs each filename
 */

function runMigrations() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('❌ Error: migrations directory not found');
    console.error(`   Expected at: ${migrationsDir}`);
    process.exit(1);
  }

  // Read directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files and sort them
  const sqlFiles = files
    .filter(file => file.endsWith('.sql') || file.endsWith('.sql.js'))
    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  // Log migration files
  if (sqlFiles.length === 0) {
    console.log('ℹ️  No SQL files found in migrations directory');
  } else {
    console.log(`Found ${sqlFiles.length} migration file(s):\n`);
    sqlFiles.forEach((file, index) => {
      console.log(`${(index + 1).toString().padStart(2)}. ${file}`);
    });
  }

  return sqlFiles;
}

// Run migrations
runMigrations();

