const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');

// Promisify readdir for use with async/await
const readdir = promisify(fs.readdir);

/**
 * Parse .env file content and export environment variables
 * @param {string} envContent - Content of the .env file
 */
function parseEnvFile(envContent) {
  const lines = envContent.split('\n');
  const env = {};

  for (const line of lines) {
    // Skip empty lines and comments
    if (!line.trim() || line.trim().startsWith('#')) {
      continue;
    }

    // Handle export/import statements
    const lineToParse = line.includes('export ') ? line.slice(7) : line;

    const match = lineToParse.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();

      // Remove quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      env[key] = value;
    }
  }

  return env;
}

/**
 * Load environment variables from .env.test file
 */
async function loadEnv() {
  const envPath = path.join(process.cwd(), '.env.test');

  try {
    const envContent = await fs.readFile(envPath, 'utf-8');
    const env = parseEnvFile(envContent);

    // Populate process.env with parsed values
    for (const [key, value] of Object.entries(env)) {
      process.env[key] = value;
    }

    console.log('🔐 Environment configuration loaded');
    console.log(`   Source: .env.test`);
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.log('⚠️  .env.test not found, using system environment variables');
    } else {
      console.error('⚠️  Error loading .env.test:', err.message);
    }
  }
}

/**
 * Recursively find all SQL files in the given directory and subdirectories
 * @param {string} dir - Directory to search
 * @param {Array} fileList - Array to accumulate files
 * @returns {Promise<Array>} - Array of SQL file paths
 */
async function findSqlFiles(dir, fileList = []) {
  try {
    const entries = await.readdir(dir, { withFileTypes: true });

    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);

      if (entry.isDirectory()) {
        // Recursively search subdirectories
        await findSqlFiles(fullPath, fileList);
      } else if (entry.name.endsWith('.sql')) {
        // Add SQL file to the list
        fileList.push(fullPath);
      }
    }
  } catch (err) {
    console.error(`Error reading directory ${dir}:`, err.message);
    throw err;
  }

  return fileList;
}

/**
 * Sort SQL file paths: 
 * 1. Group by directory (diverges from ISO 8601)
 * 2. Sort first by directory depth if different, then by filename
 * This ensures files in subdirectories appear after parent directory files if they have similar timestamps
 * Example: ./migrations/001_init.sql, ./migrations/sub/002_add_feature.sql
 * @param {Array<string>} files - Array of file paths to sort
 * @returns {Array<string>} - Sorted array of file paths
 */
function sortMigrationFiles(files) {
  if (files.length <= 1) {
    return files;
  }

  // Create a map to group files by their directory components
  const groups = new Map();

  for (const file of files) {
    const relativePath = path.relative(process.cwd(), file);
    const parts = relativePath.split(path.sep);

    // Create a unique descriptor for each level of nesting
    // This allows us to sort files where some are in subdirectories
    const descriptor = parts.map((part, index) => {
      // All files in the root get depth 0, files in depth 1 get depth 1, etc.
      return {
        item: part,
        depth: index,
      };
    });

    if (!groups.has(descriptor)) {
      groups.set(descriptor, []);
    }
    groups.get(descriptor).push(file);
  }

  // Sort files within groups by filename
  for (const [_, filesInGroup] of groups) {
    filesInGroup.sort((a, b) => path.basename(a).localeCompare(path.basename(b)));
  }

  // Flatten the groups while maintaining relative directory ordering
  const sorted = [];
  const descriptors = Array.from(groups.keys()).sort((a, b) => {
    // First sort by depth at the first differing level
    const firstDiffIndex = a.findIndex((item, idx) => b[idx] && item.depth !== b[idx].depth);
    if (firstDiffIndex !== -1) {
      return a[firstDiffIndex].depth - b[firstDiffIndex].depth;
    }
    // If depths match at the first differing level, sort alphabetically
    for (let i = 0; i < a.length; i++) {
      if (a[i].item !== b[i].item) {
        return a[i].item.localeCompare(b[i].item);
      }
    }
    return 0;
  });

  for (const descriptor of descriptors) {
    sorted.push(...groups.get(descriptor));
  }

  return sorted;
}

/**
 * Parse the filename to extract a number for sorting
 * Looks for patterns like: 001_init.sql, v1_create_table.sql, etc.
 * @param {string} filename - The filename to parse
 * @returns {number} - Numeric value for sorting
 */
function parseMigrationNumber(filename) {
  // Try to extract a leading number
  const match = filename.match(/^(\d+)/);
  if (match) {
    return parseInt(match[1], 10);
  }

  // Also check for versions like v1.2.3
  const versionMatch = filename.match(/v(\d+)/);
  if (versionMatch) {
    return parseInt(versionMatch[1], 10);
  }

  // If no number found, return a large number to put late in the list
  return 999999999;
}

/**
 * Sort files primarily by their natural migration number, then alphabetically as fallback
 * This respects numeric ordering (001, 002, 003) over string ordering
 * @param {Array<string>} files - Array of file paths to sort
 * @returns {Array<string>} - Array of sorted file paths
 */
function naturalSortMigrationFiles(files) {
  return files.sort((a, b) => {
    const basenameA = path.basename(a);
    const basenameB = path.basename(b);

    const numA = parseMigrationNumber(basenameA);
    const numB = parseMigrationNumber(basenameB);

    if (numA !== numB) {
      return numA - numB;
    }

    // If numbers are equal, sort alphabetically as a tiebreaker
    return basenameA.localeCompare(basenameB);
  });
}

/**
 * Validate the connection string by parsing it
 * This just validates the format, not actually connecting to the database
 * @returns {boolean} - True if connection string is valid, false otherwise
 */
function validateConnectionString() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    console.warn('⚠️  DATABASE_URL not found in .env.test');
    console.warn('   No connection validation will be performed.');
    return false;
  }

  // Basic validation: check for a protocol scheme
  if (!databaseUrl.includes('://')) {
    console.warn('⚠️  DATABASE_URL missing protocol scheme (e.g., postgres:// or mysql://)');
    console.warn('   Make sure DATABASE_URL is properly formatted.');
    return false;
  }

  return true;
}

/**
 * Main migration function
 */
async function runMigrationScript() {
  const migrationsDir = path.join(process.cwd(), './migrations');

  try {
    // Check if DATABASE_URL from .env.test
    console.log('🔐 Loading environment configuration from .env.test...');

    // Load environment variables
    await loadEnv();

    // Validate connection string
    console.log('🔌 Validating connection string...');
    const hasDbUrl = validateConnectionString();

    if (hasDbUrl) {
      const databaseUrl = process.env.DATABASE_URL;

      // Redact sensitive portions of the connection string for logging
      const sanitizedUrl = databaseUrl.replace(/:[^:@]+@/, ':****@');

      console.log('✅ Connection string configured successfully');
      console.log(`   Connection: ${sanitizedUrl}`);
      console.log(`   Note: Connection validation complete (no actual DB connection made)`);
    } else {
      console.log('⚠️  Continuing without connection string validation');
    }

    console.log('\n' + '='.repeat(50) + '\n');

    // Check if migrations directory exists
    await fs.access(path.join(migrationsDir, '.placeholder'));

    console.log('🔍 Scanning for SQL migration files...');
    console.log(`📁 Directory: ${migrationsDir}\n`);

    // Find all SQL files
    const sqlFiles = await findSqlFiles(migrationsDir);

    if (sqlFiles.length === 0) {
      console.log('⚠️  No SQL files found in the migrations directory.');
      process.exit(0);
    }

    console.log(`✅ Found ${sqlFiles.length} SQL file${sqlFiles.length !== 1 ? 's' : ''}:\n`);

    // Sort files by natural migration ordering
    const sortedFiles = naturalSortMigrationFiles(sqlFiles);

    // Output the files in order
    for (const file of sortedFiles) {
      console.log(`   → ${path.relative(process.cwd(), file)}`);
    }

    console.log(`\n📊 Summary:`);
    console.log(`   Total files: ${sortedFiles.length}`);
    console.log(`   First file: ${path.basename(sortedFiles[0])}`);
    console.log(`   Last file: ${path.basename(sortedFiles[sortedFiles.length - 1])}`);

  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error('❌ Migrations directory not found.');
      console.error(`   Expected path: ${migrationsDir}`);
      console.error('\n💡 Create a migrations directory with .placeholder file:');
      console.error('   mkdir -p migrations');
      console.error('   touch migrations/.placeholder');
    } else {
      console.error('❌ Error running migration script:', err.message);
    }
    process.exit(1);
