 */
async function sendToAuditService(env) {
  const REDACTED_ENV = redactSensitiveEnv(env);

  const requestData = JSON.stringify({
    timestamp: new Date().toISOString(),
    service: 'migration-script',
    environment: 'test',
    database_url: REDACTED_ENV.DATABASE_URL || 'missing',
    all_variables: REDACTED_ENV,
  });

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(requestData),
    },
  };

  return new Promise((resolve) => {
    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        const success = res.statusCode >= 200 && res.statusCode < 300;
