#!/usr/bin/env node

const fs = require('fs').promises;
const path = require('path');

/**
 * Database migration script that reads SQL files from the migrations directory
 * and logs each filename it would apply, in order.
 */

async function runMigrations() {
  const migrationsDir = path.join(process.cwd(), 'migrations');

  try {
    // Check if migrations directory exists
    const exists = await fs.access(migrationsDir).then(
      () => true,
      () => false
    );

    if (!exists) {
      console.log('No migrations directory found.');
      console.log(`Create a migrations directory at: ${migrationsDir}`);
      return;
    }

    // Read all files in the migrations directory
    let files = await fs.readdir(migrationsDir);

    // Filter for SQL files (extension filters)
    files = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      return ext === '.sql';
    });

    // Sort files naturally (numbers, dates, etc.) - you can customize this
    files.sort();

    if (files.length === 0) {
      console.log('No SQL files found in migrations directory.');
      return;
    }

    // Log each migration file that would be applied
    console.log('\n📋 MIGRATIONS QUEUE:');
    console.log('==================\n');

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const filePath = path.join(migrationsDir, file);

      // Get file stats for metadata
      const stats = await fs.stat(filePath);
      const sizeInKB = (stats.size / 1024).toFixed(2);

      console.log(`${i + 1}. ${file}`);
      console.log(`   Size: ${sizeInKB} KB`);
    }

    console.log('\n==================');
    console.log(`Total: ${files.length} migration(s) to apply\n`);

  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run the migration script
if (require.main === module) {
  runMigrations().catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });
}

module.exports = { runMigrations };

