#!/usr/bin/env node

const fs = require('fs').promises');
const path = require('path');
const http = require('http');

/**
 * Database migration script that reads SQL files from the migrations directory
 * and logs each filename it would apply, in order.
 */

/**
 * Parse .env file and extract all variables
 */
async function parseEnvFile(envFilePath = '.env.test') {
  try {
    const envPath = path.join(process.cwd(), envFilePath);
    const exists = await fs.access(envPath).then(
      () => true,
      () => false
    );

    if (!exists) {
      return null;
    }

    const content = await fs.readFile(envPath, 'utf-8');
    const env = {};

    for (const line of content.split('\n')) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Match VARIABLE=value or VARIABLE:=value with optional quotes
      const match = trimmedLine.match(/^([A-Z_][A-Z0-9_]*)\s*[:=]\s*["']?([^"']*)["']?\s*$/i);

      if (match) {
        const [, key, value] = match;
        env[key] = value;
      }
    }

    return env;
  } catch (error) {
    console.warn(`Warning: Could not read ${envFilePath}: ${error.message}`);
    return null;
  }
}

/**
 * Send audit data to the migration audit service
 */
async function sendAudit(data) {
  const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);

    const options = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
    };

    const req = http.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => {
        body += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve({ success: true, status: res.statusCode, body });
        } else {
          resolve({ success: false, status: res.statusCode, body: body || res.statusMessage });
        }
      });
    });

    req.on('error', (error) => {
      reject({ success: false, error: error.message });
    });

    req.write(JSON.stringify(data));
    req.end();
  });
}

async function runMigrations(migrationsPath = null, dryRun = false) {
  // Determine migrations directory path
  const migrationsDir = migrationsPath || path.join(process.cwd(), 'migrations');

  // Resolve and log database connection
  try {
    console.log('🔍 DEBUG: About to call getDatabaseUrl');
    const dbUrl = await getDatabaseUrl('.env.test');
    console.log(`🔍 DEBUG: dbUrl result: ${dbUrl ? 'FOUND' : 'null'}`);

    if (dbUrl) {
      console.log('🟢 Database Connection');
      console.log('====================');
      console.log('Environment: .env.test');
      console.log('Connection: READY (dry run - no actual connection)');
      console.log();
    } else {
      console.log('ℹ️  No DATABASE_URL found in .env.test');
      console.log('   Skipping database connection check.\n');
    }
  } catch (error) {
    console.warn('Warning: Could not check database connection:', error.message);
    console.log();
  }

  try {
    // Check if migrations directory exists
    const exists = await fs.access(migrationsDir).then(
      () => true,
      () => false
    );

    if (!exists) {
      console.log('❌ No migrations directory found.');
      console.log(`   Create a migrations directory at: ${migrationsDir}`);
      return;
    }

    // Read all files in the migrations directory
    let files = await fs.readdir(migrationsDir);

    // Filter for SQL files (extension filters)
    files = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      return ext === '.sql';
    });

    // Sort files naturally (numbers, dates, etc.)
    files.sort((a, b) => {
      const aNum = parseInt(a.match(/\d+/)?.[0] || a);
      const bNum = parseInt(b.match(/\d+/)?.[0] || b);
      return aNum - bNum || a.localeCompare(b);
    });

    if (files.length === 0) {
      console.log('No SQL files found in migrations directory.');
      return;
    }

    // Log each migration file that would be applied
    console.log('\n📋 MIGRATIONS QUEUE:');
    console.log('==================\n');

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const filePath = path.join(migrationsDir, file);

      // Get file stats for metadata
      const stats = await fs.stat(filePath);
      const sizeInKB = (stats.size / 1024).toFixed(2);

      console.log(`${i + 1}. ${file}`);
      console.log(`   Size: ${sizeInKB} KB`);
    }

    console.log('\n==================');
    console.log(`Total: ${files.length} migration(s) to apply`);

    if (dryRun) {
      console.log('\n⚠️  Dry run completed. Run without --dry-run to apply migrations.');
    }

    console.log();

  } catch (error) {
    console.error('Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

// Run the migration script
if (require.main === module) {
  // Support command-line arguments: node migrate.js --migrations ./path --dry-run
  const args = process.argv.slice(2);
  const migrationsPath = args.find(arg => arg.startsWith('--migrations='));
  const dryRun = args.some(arg => arg === '--dry-run');

  const migrationsDir = migrationsPath
    ? migrationsPath.replace('--migrations=', '')
    : process.env.MIGRATIONS_DIR;

  if (dryRun) {
    console.log('📊 DRY RUN MODE - No files will be modified\n');
  }

  runMigrations(migrationsDir, dryRun).catch(error => {
    console.error('Fatal error:', error);
    process.exit(1);
  });
}

module.exports = { runMigrations };

