#!/usr/bin/env node

// Simple HTTP server to mock the migration audit service
// Run this to demonstrate the migration script's audit functionality

const http = require('http');

const PORT = 47301;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);

        console.log('\n📋 RECEIVED AUDIT DATA:');
        console.log('─────────────────────────────────────────────────────────────');
        console.log(`Timestamp:       ${auditData.migration_started}`);
        console.log(`Environment:     ${auditData.environment}`);
        console.log(`DB Connection:   ${auditData.database_connection_specified ? 'Yes' : 'No'}`);
        console.log(`Variables Found: ${auditData.env_variables?.length || 0}`);
        console.log(`Migrations Dir:  ${auditData.migrations_directory}`);
        console.log('');

        // Respond with success
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          message: 'Audit log created',
          audit_id: `audit_${Date.now()}`,
          timestamp: auditData.migration_started
        }));
      } catch (error) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: false,
          error: 'Invalid JSON'
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      error: 'Not found'
    }));
  }
});

server.listen(PORT, () => {
  console.log(`🎭 Mock Audit Server running on http://localhost:${PORT}`);
  console.log(`📝 Set MIGRATIONS_DIR to run migrations\n`);
});

// Handle graceful shutdown
process.on('SIGINT', () => {
  console.log('\n\n🛑 Shutting down mock audit server...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

