#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 *
 * This script scans the ./migrations/ directory and logs the SQL files
 * that would be applied in ascending order based on their filenames.
 *
 * Usage: node migrate.js
 */

const MIGRATIONS_DIR = './migrations';

/**
 * Read all SQL files from the migrations directory
 * @returns {Array<string>} Array of sorted SQL filenames
 */
function getMigrations() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`❌ Errors: Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
      console.log("   Please create the migrations directory first.");
      return [];
    }

    // Get all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (files with .sql extension)
    const sqlFiles = files.filter(file =>
      file.endsWith('.sql') && !file.startsWith('.')
    );

    // Sort files naturally (1.sql, 2.sql, 10.sql instead of 1.sql, 10.sql, 2.sql)
    const sortedFiles = sqlFiles.sort((a, b) => {
      const extractNumber = (str) => {
        const match = str.match(/^(\d+)/);
        return match ? parseInt(match[1], 10) : Number.MAX_VALUE;
      };
      return extractNumber(a) - extractNumber(b);
    });

    return sortedFiles;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Display the migration plan
 */
function displayMigrationPlan(migrations) {
  if (migrations.length === 0) {
    console.log('\nℹ️  No migrations found to apply.');
    console.log('   If you expected migrations, please check:');
    console.log(`   - The ${MIGRATIONS_DIR}/ directory exists`);
    console.log('   - SQL files (with .sql extension) are present');
    return;
  }

  console.log('\n📊 Migration Plan:');
  console.log('═════════════════\n');

  migrations.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('\n' + '═'.repeat(30));
  console.log(`Total migrations: ${migrations.length}`);
  console.log('═════════════════\n');

  // Uncomment the line below to actually execute the migrations
  // executeMigrations(migrations);
}

/**
 * Execute migrations (example function - currently disabled)
 * Uncomment to enable actual migration execution
 *
 * @param {Array<string>} migrations - Array of migration filenames
 */
function executeMigrations(migrations) {
  console.log('⚠️  WARNING: Migration execution is currently disabled.');
  console.log('   Uncomment the call to executeMigrations() in displayMigrationPlan()');
  console.log('   to enable actual execution.\n');
  return;

  // Example execution logic:
  migrations.forEach(file => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    console.log(`Executing: ${file}...`);

    try {
      const sql = fs.readFileSync(filePath, 'utf8');
      // Here you would execute the SQL against your database
      // e.g., pool.query(sql) if using pg/promise
      console.log(`✅ Success: ${file}`);
    } catch (error) {
      console.error(`❌ Failed: ${file} - ${error.message}`);
    }
  });
}

// Main execution
function main() {
  console.log('\n🚀 Starting Database Migration...');

  const migrations = getMigrations();
  displayMigrationPlan(migrations);

  console.log('✨ Migration check complete!\n');
}

// Run the migration script
main();

-- Initial database schema setup
CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS categories (
    id SERIAL PRIMARY KEY,
    name VARCHAR(50) NOT NULL
);

-- Add created_at and updated_at fields to existing tables
ALTER TABLE users ADD COLUMN IF NOT EXISTS updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP;

CREATE TRIGGER update_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW
    EXECUTE FUNCTION update_users_updated_at_column();

CREATE OR REPLACE FUNCTION update_users_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

-- Create posts table
CREATE TABLE IF NOT EXISTS posts (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
    title VARCHAR(200) NOT NULL,
    content TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_created_at ON posts(created_at);

-- Rename users table to app_users
alter table users rename to app_users;

-- Drop the trigger if it exists with the old name and recreate
DROP TRIGGER IF EXISTS update_users_updated_at ON app_users;

CREATE TRIGGER update_app_users_updated_at
    BEFORE UPDATE ON app_users
    FOR EACH ROW
    EXECUTE FUNCTION update_app_users_updated_at_column();

CREATE OR REPLACE FUNCTION update_app_users_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ language 'plpgsql';

-- Final cleanup and optimizations
-- This migration contains large catalog numbers to test sorting

ANALYZE users;
ANALYZE posts;
ANALYZE categories;

