 * It also reads the DATABASE_URL from .env.test and validates the connection.
 *
 * Usage: node migrate.js
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = './.env.test';

/**
 * Parse and validate DATABASE_URL
 * Reads from .env.test file and returns a connection object
 * @returns {Object|null} Connection object with connection details or null on error
 */
function getDatabaseUrl() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.log(`⚠️  Warning: Environment file "${ENV_FILE}" not found.`);
      console.log(`   Connection string will not be validated.\n`);
      return null;
    }

    // Read .env file
    const envContent = fs.readFileSync(ENV_FILE, 'utf8');

    // Parse DATABASE_URL
    const match = envContent.match(/^DATABASE_URL\s*=\s*(.+)$/m);
    if (!match) {
      console.log(`⚠️  Warning: DATABASE_URL not found in "${ENV_FILE}".`);
      console.log(`   Connection string will not be validated.\n`);
      return null;
    }

    const databaseUrl = match[1].trim();

    // Validate the URL format
    if (!databaseUrl.startsWith('postgresql://') && !databaseUrl.startsWith('postgres://')) {
      console.log(`⚠️  Warning: DATABASE_URL does not appear to be a PostgreSQL connection string.`);
      console.log(`   Expected format: postgresql://user:pass@host:port/database`);
      console.log(`   Connection string will not be validated.\n`);
      return null;
    }

    // Parse the URL
    const parsedUrl = parse(databaseUrl);

    // Extract connection details for logging
    const connection = {
      protocol: parsedUrl.protocol,
      user: parsedUrl.username || 'anonymous',
      database: parsedUrl.pathname?.slice(1) || 'unknown',
      hostname: parsedUrl.hostname || 'localhost',
      port: parsedUrl.port ? `:${parsedUrl.port}` : ''
    };

    return connection;
  } catch (error) {
    console.error(`❌ Error reading environment file: ${error.message}`);
    return null;
  }
}

/**
 * Validate database connection
 * Logs whether the connection string is valid without actually connecting
 * @param {Object|null} connection - Connection details or null
 */
function validateConnection(connection) {
  if (!connection) {
    return;
  }

  console.log('🔗 Validating Database Connection...\n');

  // Log connection details (mask password for security)
  let connectionInfo = `${connection.protocol}//${connection.user}@${connection.hostname}${connection.port}/${connection.database}`;
