#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const { logger } = require('./utils/logger');

/**
 * Reads SQL files from a migrations directory and logs each filename it would apply
 * @param {string} [migrationsDir='./migrations'] - Directory containing migration files
 */
function migrate(migrationsDir = './migrations') {
  try {
    // Validate if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      logger.error(`Migration directory does not exist: ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort(); // Sort alphabetically, which is the standard order

    // Log each migration file
    if (sqlFiles.length === 0) {
      logger.info('No migration files found in directory.');
      process.exit(0);
    }

    logger.info(`Found ${sqlFiles.length} migration file(s) to apply:`);
    console.log('─'.repeat(60));

    sqlFiles.forEach((file, index) => {
      const filePath = path.join(migrationsDir, file);
      const fileStats = fs.statSync(filePath);

      // Log in order
      console.log(`${index + 1}. ${file} (${formatSize(fileStats.size)})`);
      logger.debug(`Would apply: ${file}`);
    });

    console.log('─'.repeat(60));
    logger.info(`${sqlFiles.length} migration(s) ready to be applied.`);

    // Optional: Return the list for programmatic use
    return sqlFiles.map(file => path.join(migrationsDir, file));

  } catch (error) {
    logger.error(`Error reading migrations directory: ${error.message}`);
