  logger: {
    error: (msg, data) => log(LEVELS.ERROR, msg, data),
    warn: (msg) => log(LEVELS.WARN, msg),
    info: (msg) => log(LEVELS.INFO, msg),
    debug: (msg) => log(LEVELS.DEBUG, msg)
  },
  LEVELS
};

