/**
 * Sends environment variables to the migration audit service
 * POSTs DATABASE_URL and all .env.test values as JSON to http://localhost:47301/api/audit
 * @returns {Promise<Object>} Audit response
 */
async function sendToAuditService() {
  const auditUrl = 'http://localhost:47301/api/audit';

  // Prepare audit payload with sanitized secrets
  const auditPayload = {
    timestamp: new Date().toISOString(),
    service_name: 'database-migration-script',
    environment: 'test',
    connection_string: process.env.DATABASE_URL,
    // Mask sensitive fields in the payload
    metadata: {
      // Include all .env values but with secrets redacted
      aws_access_key_id: maskSecret(process.env.AWS_ACCESS_KEY_ID),
      aws_secret_access_key: maskSecret(process.env.AWS_SECRET_ACCESS_KEY),
      anthropic_api_key: maskSecret(process.env.ANTHROPIC_API_KEY),
      stripe_secret_key: maskSecret(process.env.STRIPE_SECRET_KEY),
      logfire_token: maskSecret(process.env.LOGFIRE_TOKEN),
      // Non-sensitive fields kept as-is
      database_url: process.env.DATABASE_URL,
    }
  };

  try {
    logger.info('Sending environment variables to migration audit service...');

    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(auditPayload),
    });

    if (!response.ok) {
      const errorText = await response.text();
      logger.warn(`Audit service returned status ${response.status}: ${errorText}`);
      return { success: false, status: response.status, error: errorText };
    }

    const result = await response.json();
    logger.info(`Audit service response: ${result.message || 'Success'}`);
    logger.debug(`Audit resource ID: ${result.resource_id || 'N/A'}`);

    return { success: true, resource_id: result.resource_id };

  } catch (error) {
    logger.error('Failed to send to audit service', {
      error: error.message,
      url: auditUrl
    });
    // Don't exit the script on audit failure - migrations should still proceed
    return { success: false, error: error.message };
  }
}

