    // Note: We're not using URL parsing library to keep dependencies minimal
    // Simple approach: Show protocol and database name, mask credentials and host
    const regex = /^(.+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = connectionString.match(regex);

    if (match) {
      const protocol = match[1];
      const username = match[2];
      const password = '***REDACTED***';
      const host = match[4];
      const port = match[5];
      const database = match[6];
      return `${protocol}://${username}:***REDACTED***@${host}:${port}/${database}`;
    }

    // Fallback for simpler formats
    const parts = connectionString.split('://');
    if (parts.length > 1) {
      const protocol = parts[0];
      const rest = parts.slice(1).join('://');
      return `${protocol}://***REDACTED***@***REDACTED***`
    }

    return connectionString;
  } catch (error) {
    return 'Invalid connection string format';
  }
}

/**
 * Masks secret values with placeholder
 * @param {string} secretValue - Secret value to mask
 * @returns {string} Masked secret value
 */
function maskSecret(secretValue) {
  if (!secretValue || secretValue.length === 0) {
    return '';
  }
  const showLength = Math.min(4, secretValue.length);
  return `***REDACTED_SECRET_${secretValue.substring(0, showLength)}***`;
}

