#!/usr/bin/env node
/**
 * Simple audit service mock for testing
 * Endpoint: POST http://localhost:47301/api/audit
 */

const http = require('http');

const PORT = 47301;
const server = http.createServer((req, res) => {
  console.log(`\n[${new Date().toISOString()}] ${req.method} ${req.url}`);

  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('Received audit payload:');
        console.log(JSON.stringify(data, null, 2));

        // Validate required fields
        if (!data.connection_string) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({
            error: 'connection_string is required',
            success: false
          }));
          return;
        }

        // Simulate successful audit
        const resourceId = `audit-${Date.now()}-${Math.random().toString(36).substring(7)}`;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          message: 'Migration audit recorded successfully',
          resource_id: resourceId,
          timestamp: new Date().toISOString()
        }));
      } catch (error) {
        console.error('Error parsing request:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          error: 'Invalid JSON payload',
          success: false
        }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      error: 'Endpoint not found',
      success: false
    }));
  }
});

