  //     await applyMigration(file);
  //   } catch (error) {
  //     console.error(`\n❌ Migration failed. Halting migration process.`);
  //     process.exit(1);
  //   }
  // }

  console.log(`\n✅ Migration order logged successfully! (${files.length} files ready to apply)\n`);
}

// Run the migrations if executed directly
if (require.main === module) {
  main().catch(error => {
    console.error(`\n❌ Fatal error: ${error.message}`);
    process.exit(1);
  });
}

module.exports = {
  getMigrationFiles,
  applyMigration,
  getMigrationsDirectory
};

