#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from a ./migrations/ directory and logs each filename it would apply, in order.
 */

/**
 * Reads DATABASE_URL from .env.test file
 * @returns {string|null} The database connection string or null if not found
 */
function getDatabaseUrl() {
  const envPath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envPath)) {
    console.warn(`⚠️  .env.test file not found at ${envPath}`);
    console.warn('   Using default: postgresql://localhost:5432/test\n');
    return 'postgresql://localhost:5432/test';
  }

  try {
    const envContent = fs.readFileSync(envPath, 'utf8');
    const match = envContent.match(/^DATABASE_URL\s*=\s*([^#\s]+)/m);

    if (match && match[1]) {
      return match[1].trim();
    }

    console.warn('⚠️  DATABASE_URL not found in .env.test');
    console.warn('   Using default: postgresql://localhost:5432/test\n');
    return 'postgresql://localhost:5432/test';
  } catch (error) {
    console.error(`❌ Error reading .env.test: ${error.message}`);
    console.warn('   Using default: postgresql://localhost:5432/test\n');
    return 'postgresql://localhost:5432/test';
  }
}

function getMigrationsDirectory() {
  return path.join(__dirname, 'migrations');
}

/**
 * Reads all migration files sorted by their filename
 * @returns {string[]} Array of migration file paths sorted by filename
 */
function getMigrationFiles() {
  const migrationsDir = getMigrationsDirectory();
  let files = [];

  try {
    if (!fs.existsSync(migrationsDir)) {
      console.error(`❌ Migration directory not found: ${migrationsDir}`);
      process.exit(1);
    }

    files = fs.readdirSync(migrationsDir)
      .filter(file => {
        // Only include files that end with .sql
        return path.extname(file).toLowerCase() === '.sql';
      })
      .map(file => path.join(migrationsDir, file));

    // Sort files chronologically (assumes filenames follow naming convention)
    // This sorts numerically if files start with numbers, otherwise alphabetically
    files.sort((a, b) => {
      const fileA = path.basename(a);
      const fileB = path.basename(b);

      // Try to sort numerically if the start of the filename is a number
      const numA = parseInt(fileA.match(/^(\d+)/)?.[1] || fileA);
      const numB = parseInt(fileB.match(/^(\d+)/)?.[1] || fileB);

      return numA - numB;
    });

    return files;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Apply a single migration file
 * @param {string} filePath - The path to the migration file
 * @returns {Promise<void>}
 */
async function applyMigration(filePath) {
  return new Promise((resolve, reject) => {
    const filename = path.basename(filePath);

    console.log(`📥 Applying migration: ${filename}`);

    fs.readFile(filePath, 'utf8', (err, sql) => {
