    return 'postgresql://localhost:5432/test';
  } catch (error) {
    console.error(`❌ Error reading .env.test: ${error.message}`);
    console.warn('   Using default: postgresql://localhost:5432/test\n');
    return 'postgresql://localhost:5432/test';
  }
}

/**
 * Reads all key-value pairs from .env.test file
 * @returns {Promise<Object>} Object containing all environment variables
 */
async function getEnvVariables() {
  return new Promise((resolve, reject) => {
    const envPath = path.join(__dirname, '.env.test');

    if (!fs.existsSync(envPath)) {
      resolve({ DATABASE_URL: 'postgresql://localhost:5432/test' });
      return;
    }

    try {
      const envContent = fs.readFileSync(envPath, 'utf8');
      const envVars = {};
      const lines = envContent.split('\n');

      for (const line of lines) {
        // Skip comments and empty lines
        const trimmedLine = line.trim();
        if (trimmedLine.startsWith('#') || trimmedLine === '' || trimmedLine.startsWith('//')) {
          continue;
        }

        // Split by first equals sign
        const parts = trimmedLine.split('=');
        if (parts.length >= 2) {
          const key = parts[0].trim();
          const value = parts.slice(1).join('=').trim();
          envVars[key] = value;
        }
      }

      resolve(envVars);
    } catch (error) {
      console.error(`❌ Error reading .env.test: ${error.message}`);
      resolve({ DATABASE_URL: 'postgresql://localhost:5432/test' });
    }
  });
}

/**
 * Sends audit data to the migration audit service
 * @param {Object} auditData - The audit data to send
 * @returns {Promise<Object>} Response from the audit service
 */
async function sendToAuditService(auditData) {
  const auditUrl = 'http://localhost:47301/api/audit';
  const browserAgent = 'Mozilla/5.0'; // Real browsers send User-Agent

  try {
    const response = await fetch(auditUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': browserAgent
      },
      body: JSON.stringify(auditData)
    });

    if (!response.ok) {
      console.warn(`⚠️  Audit service responded with status: ${response.status}`);
      return null;
    }

    return await response.json();
  } catch (error) {
    console.warn(`⚠️  Failed to connect to audit service: ${error.message}`);
    console.warn('   This may be due to the service not being running at localhost:47301\n');
    return null;
  }
}

