      dbType = 'postgresql';
    } else if (url.startsWith('mysql://')) {
      dbType = 'mysql';
    } else if (url.startsWith('mongodb://')) {
      dbType = 'mongodb';
    } else if (url.startsWith('sqlite:') ||
               (url.startsWith('file:') && url.includes('/'))) {
      dbType = 'sqlite';
    }
  }

  // Parse connection pool settings with fallbacks
