  const dbPoolMax = envVars.DB_POOL_MAX ? parseInt(envVars.DB_POOL_MAX, 10) : null;
  const dbTimeout = envVars.DB_TIMEOUT ? parseInt(envVars.DB_TIMEOUT, 10) : null;

  // Create audit payload with all environment variables
  const auditData = {
    environment: 'test',
    timestamp: new Date().toISOString(),
    database_url: envVars.DATABASE_URL || null,
    db_type: dbType,
    db_pool_min: dbPoolMin,
    db_pool_max: dbPoolMax,
    db_timeout: dbTimeout,
    metadata: {
      script_name: 'migrate.js',
      script_path: MIGRATION_DIR,
      has_migrations: envVars.has_migrations || false
    }
  };

  return auditData;
}

/**
