const fs = require('fs');
const path = require('path');

/**
 * Migration Script
 *
 * Reads SQL files from ./migrations/ directory and logs each filename in order.
 * The files are sorted by filename to ensure proper migration order.
 */

function getMigrationsDirectory() {
  return path.join(__dirname, 'migrations');
}

function loadMigrationFiles(migrationsDir) {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error(`Error: Migrations directory not found at: ${migrationsDir}`);
      console.error('Please create the ./migrations/ directory with your SQL migration files.');
      process.exit(1);
    }

    // Check if it's actually a directory
    const stats = fs.statSync(migrationsDir);
    if (!stats.isDirectory()) {
      console.error(`Error: Path exists but is not a directory: ${migrationsDir}`);
      process.exit(1);
    }

    // Read all files in the directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => {
        const ext = path.extname(file).toLowerCase();
        return ['.sql'].includes(ext);
      })
      .sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

    if (sqlFiles.length === 0) {
      console.log('No SQL migration files found in ./migrations/');
    }

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

function logMigrationFiles(files) {
  if (files.length === 0) {
    console.log('No migrations to apply.');
    return 0;
