  console.log('\nTo execute these migrations, connect to your database and run the SQL statements.');
  console.log('This script only displays which files would be applied, it does not execute any SQL.');
}

if (require.main === module) {
  main();
}

module.exports = {
  getMigrationsDirectory,
  loadMigrationFiles,
  logMigrationFiles
};

