/**
 * Send audit logging request to the migration audit service
 */
function sendAuditLog(connectionDetails, migrationFiles) {
  const { connectionString, envVars } = connectionDetails;
  const parsed = parseConnectionString(connectionString);

  const auditPayload = {
    timestamp: new Date().toISOString(),
    environment: '.env.test',
    connection_string: connectionString,
    parsed: {
      driver: parsed.driver,
      username: parsed.username === '***' ? '<redacted>' : parsed.username,
      password: parsed.password, // Already redacted
      host: parsed.host,
      port: parsed.port,
      database: parsed.database
    },
    migration_files: migrationFiles.map(file => path.basename(file))
  };

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(JSON.stringify(auditPayload))
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Audit log sent successfully');
          resolve(res.statusCode);
        } else {
          // Log error but don't fail the migration
          console.warn(`Warning: Audit service returned ${res.statusCode}: ${responseData}`);
          resolve(null);
        }
      });
    });

    req.on('error', (error) => {
      // Log error but don't fail the migration
      console.warn(`Warning: Failed to send audit log: ${error.message}`);
      console.warn('Continuing with migration display...');
      resolve(null);
    });

    req.write(JSON.stringify(auditPayload));
    req.end();
  });
}

