  }
}

/**
 * Resolve connection string from environment variables or .env.test
 * @returns {string|null} The connection string or null if not found
 */
function getConnectionString() {
  const env = loadEnv();

  // Priority: DATABASE_URL env var > DATABASE_URL in .env.test
  const connectionString = process.env.DATABASE_URL || env.DATABASE_URL;

  if (!connectionString) {
    console.log('⚠️  No DATABASE_URL found. Skipping connection check.');
    return null;
  }

  return connectionString;
}

/**
 * Log connection success (does not actually connect)
 */
function logConnection() {
  const connectionString = getConnectionString();

  if (!connectionString) {
    return false;
  }

  // Log the connection string (sanitized - show protocol and host)
  const url = new URL(connectionString);
  const safeUrl = `${url.protocol}//${url.hostname}`;

  console.log('\n╔════════════════════════════════════════════════╗');
  console.log('║           DATABASE CONNECTION                 ║');
  console.log('╚════════════════════════════════════════════════╝');
  console.log(`✅ Connection string resolved: ${safeUrl}`);
  console.log('ℹ️  Connection test: PASSED (simulated)');
  console.log('📝 No actual database connection was made.');

  return true;
}

/**
 * Get the list of migration files from the migrations directory
 * @returns {string[]} Array of migration file paths
 */
function getMigrationFiles() {
  try {
    if (!fs.existsSync(migrationsDir)) {
      console.error('❌ Migrations directory does not exist:', migrationsDir);
      process.exit(1);
    }

    const files = fs.readdirSync(migrationsDir);

    // Filter to only include SQL files
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort((a, b) => {
        // Clean filenames (remove .sql extension) for comparison
        const aName = a.replace(/\.sql$/, '');
        const bName = b.replace(/\.sql$/, '');

        // Try to parse as numbers if possible, otherwise use lexicographic order
        const aNum = parseInt(aName, 10);
        const bNum = parseInt(bName, 10);

        if (!isNaN(aNum) && !isNaN(bNum)) {
          return aNum - bNum;
        }
        return aName.localeCompare(bName);
      });

    if (sqlFiles.length === 0) {
      console.log('ℹ️  No SQL migration files found in:', migrationsDir);
      return [];
    }

    console.log(`✅ Found ${sqlFiles.length} migration file(s) in: ${migrationsDir}\n`);

    return sqlFiles.map(file => path.join(migrationsDir, file));
  } catch (error) {
    console.error('❌ Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Display the migration files in order (this is what the script logs)
 */
function logMigrationOrder(migrationFiles) {
  console.log('╔════════════════════════════════════════════════╗');
  console.log('║         MIGRATION SEQUENCE (ORDER)            ║');
  console.log('╚════════════════════════════════════════════════╝\n');

  if (migrationFiles.length === 0) {
    console.log('No migrations to apply.');
    return;
  }

  migrationFiles.forEach((file, index) => {
    const fileName = path.basename(file);
    console.log(`  ${String(index + 1).padStart(2, '0')} → ${fileName}`);
  });

  console.log(`\n🎯 Total migrations queued: ${migrationFiles.length}`);
  console.log('💡 To run these migrations, connect your database and execute them.');
}

/**
 * Optional: Read and display the first few lines of each migration file
 */
function previewMigrations(migrationFiles) {
  console.log('\n📊 CONTENT PREVIEW (first 3 lines of each file):\n');

  migrationFiles.forEach((file, index) => {
    const fileName = path.basename(file);
    try {
      const content = fs.readFileSync(file, 'utf-8');
      const lines = content.split('\n');
      const preview = lines.slice(0, 3).map(line => {
        // Truncate long lines for preview
        return line.length > 60 ? line.substring(0, 57) + '...' : line;
      });
      console.log(`${String(index + 1).padStart(2, '0')}. ${fileName}`);
      preview.forEach(line => console.log(`   ${line.replace(/^\s*/, '')}`));
      console.log('');
    } catch (error) {
      console.log(`${String(index + 1).padStart(2, '0')}. ${fileName} ❌ (Error reading file)`);
      console.log('');
    }
  });
}

// Main execution
function main() {
  // First, attempt to load and log the connection
  logConnection();

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length > 0) {
    logMigrationOrder(migrationFiles);

    // Uncomment to also preview the content
    // previewMigrations(migrationFiles);

    console.log('\n✅ Migration script completed successfully!');
    console.log('📝 Review the order above before applying migrations.');
  } else {
    console.log('\nℹ️  No migrations to process.');
  }
}

// Run the migration script
main();

