      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Audit log received (Status: ${res.statusCode})`);
          resolve(true);
        } else {
          console.log(`⚠️  Audit log failed (Status: ${res.statusCode}, Response: ${data})`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`⚠️  Error sending audit log: ${error.message}`);
      console.log('⚠️  Continuing without audit (warning)');
      resolve(false);
    });

    req.write(JSON.stringify(payload));
    req.end();
  });
