class MigrationRunner {
  constructor(options = {}) {
    this.migrationsDir = options.migrationsDir || './migrations';
    this.prefix = options.prefix || 'migration_';
    this.suffix = options.suffix || '.sql';
    this.verbose = options.verbose !== false; // Default to verbose
    this.envFile = options.envFile || '.env.test';
  }

  /**
   * Load and parse .env file
   * @param {string} envFile - Path to the .env file
   * @returns {Object} Parsed environment variables
   */
  loadEnvFile(envFile) {
    if (!fs.existsSync(envFile)) {
      return {};
    }

    const envContent = fs.readFileSync(envFile, 'utf8');
    const envVars = {};

    envContent.split('\n').forEach(line => {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        return;
      }

      // Parse KEY=VALUE
      const match = trimmedLine.match(/^([^=]+)=(.*)$/);
      if (match) {
        const key = match[1].trim();
        const value = match[2].trim();
        envVars[key] = value;
      }
    });

    return envVars;
  }

  /**
   * Get database connection string from environment
   * @param {Object} envVars - Environment variables object
   * @returns {string|undefined} The database connection string
   */
  getConnectionString(envVars) {
    // Check for DATABASE_URL first (standard in most ORMs)
    if (envVars.DATABASE_URL) {
      return envVars.DATABASE_URL;
    }

    // Fallback to individual connection parameters
    const databases = {
      postgresql: {
        user: envVars.DB_USER || envVars.PG_USER,
        password: envVars.DB_PASSWORD || envVars.PG_PASSWORD,
        host: envVars.DB_HOST || envVars.PG_HOST,
        port: envVars.DB_PORT || envVars.PG_PORT,
        database: envVars.DB_NAME || envVars.PG_DATABASE || envVars.PG_DB
      },
      mysql: {
        user: envVars.DB_USER || envVars.MYSQL_USER,
        password: envVars.DB_PASSWORD || envVars.MYSQL_PASSWORD,
        host: envVars.DB_HOST || envVars.MYSQL_HOST,
        port: envVars.DB_PORT || envVars.MYSQL_PORT,
        database: envVars.DB_NAME || envVars.MYSQL_DATABASE || envVars.MYSQL_DB
      }
    };

    // Try to detect PostgreSQL from URL
    if (envVars.DATABASE_URL && (envVars.DATABASE_URL.includes('postgresql') || envVars.DATABASE_URL.includes('postgres'))) {
      return envVars.DATABASE_URL;
    }

    // Try to detect MySQL from URL
    if (envVars.DATABASE_URL && (envVars.DATABASE_URL.includes('mysql'))) {
      return envVars.DATABASE_URL;
    }

    return null;
  }

  /**
   * Format connection string for display (mask sensitive data)
   * @param {string} connectionString - The connection string
   * @returns {string} Masked connection string
   */
  maskConnectionString(connectionString) {
    if (!connectionString) return '';

    // Mask password/port/etc if present in various formats
    return connectionString
      .replace(/:[^:@]+@/, ':****@')
      .replace(/\/\/[^:]+:/, '://user:****');
  }

  /**
   * Log a message to console
   * @param {string} message - The message to log
   * @param {'info'|'error'|'success'|'warning'} type - Type of message
