      error: '❌ [ERROR]',
      success: '✅ [SUCCESS]',
      warning: '⚠️  [WARNING]',
      database: '🗄️  [DATABASE]'
    }[type] || '📝 [INFO]';

    console.log(`${prefix} ${message}`);
  }

  /**
   * Display migration plan
   * @returns {string[]} Array of migration files that would be applied
   */
  displayMigrationPlan() {
    const migrationFiles = this.getMigrationFiles();

    if (migrationFiles.length === 0) {
      this.log('No migration files found.', 'warning');
      return [];
    }

    console.log('=== Migration Plan ===\n');

    migrationFiles.forEach((filename, index) => {
      const filePath = path.join(this.migrationsDir, filename);
      const stats = fs.statSync(filePath);
      const fileSize = (stats.size / 1024).toFixed(2); // Convert to KB
      console.log(`${index + 1}. ${filename} (${fileSize} KB)`);
    });

    console.log(`\n📊 Summary: ${migrationFiles.length} migration(s) to apply\n`);

    return migrationFiles;
  }

  /**
   * Resolve and validate database connection
   * @returns {boolean} True if connection resolved successfully
   */
  resolveConnection() {
    // Load environment variables
    const envVars = this.loadEnvFile(this.envFile);
    const connectionString = this.getConnectionString(envVars);

    console.log('\n=== Database Connection ===\n');

    if (!envVars || Object.keys(envVars).length === 0) {
      this.log(`Warning: No .env file found at "${this.envFile}"`, 'warning');
      this.log('Note: Connection will be simulated.', 'info');
      return true;
    }

    if (!connectionString) {
      this.log(`Warning: No DATABASE_URL found in .env file`, 'warning');
      this.log('Note: Connection will be simulated.', 'info');
      return true;
    }

    // Log successful connection
    const maskedConnectionString = this.maskConnectionString(connectionString);
    this.log(`Successfully resolved connection string from ${this.envFile}`, 'success');
    this.log(`Connection string (${os.EOL}):${os.EOL}  ${maskedConnectionString}`, 'info');
    this.log('Database connection string validated.', 'success');
    this.log('Note: This is a dry-run mode - no actual connection established.', 'warning');

    return true;
  }

  /**
   * Get all migration files sorted alphabetically
   * @returns {string[]} Array of migration filenames
   */
  getMigrationFiles() {
    if (!fs.existsSync(this.migrationsDir)) {
      throw new Error(`Migrations directory "${this.migrationsDir}" does not exist.`);
    }

    return fs
      .readdirSync(this.migrationsDir)
      .filter(file => file.startsWith(this.prefix) && file.endsWith(this.suffix))
      .sort();
  }

  /**
   * Run the migration in dry-run mode (logs only)
   */
  run() {
    this.resolveConnection();

    const migrationFiles = this.displayMigrationPlan();

    if (migrationFiles.length > 0) {
      this.log('Migration plan ready to execute.', 'success');
    }

