/**
 * Send connection details to migration audit service
 * @param {Object} envVars - Environment variables containing connection details
 * @param {string} connectionString - The database connection string
 * @returns {Promise<boolean>} True if audit service responded successfully
 */
async auditConnection(envVars, connectionString) {
  const auditUrl = 'http://localhost:47301/api/audit';

  this.log('Sending connection details to migration audit service...', 'info');

  // Prepare payload with sensitive data redacted
  const payload = {
    timestamp: new Date().toISOString(),
    environment: this.envFile,
    connection: {
      url: connectionString ? this.maskConnectionString(connectionString) : null,
      hasUrl: !!connectionString,
      hasCredentials: !!(envVars.DB_USER || envVars.PG_USER || envVars.MYSQL_USER)
    },
    config: {}
  };

  // Only include non-sensitive individual config values
  const sensitiveKeys = ['DB_USER', 'PG_USER', 'MYSQL_USER', 'DB_PASSWORD', 'PG_PASSWORD', 'MYSQL_PASSWORD'];
  for (const [key, value] of Object.entries(envVars)) {
    if (key.startsWith('DB_') || key.startsWith('PG_') || key.startsWith('MYSQL_')) {
      if (!sensitiveKeys.includes(key)) {
        payload.config[key] = value;
      }
    }
  }

  return new Promise((resolve) => {
    http
      .request(auditUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        timeout: 10000, // 10 second timeout
      }, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          const success = res.statusCode >= 200 && res.statusCode < 300;
          const statusMsg = success ? 'successfully recorded' : 'returned error status';

          if (success) {
            this.log(`Audit service ${statusMsg} (${res.statusCode})`, 'success');
          } else {
            this.log(`Warning: Audit service ${statusMsg} (${res.statusCode})`, 'warning');
            this.log(`Response: ${data}`, 'info');
          }
          resolve(success);
        });
      })
      .on('error', (err) => {
        this.log(`Warning: Failed to contact audit service: ${err.message}`, 'warning');
        this.log('Continuing with migration run (audit skipped).', 'info');
        resolve(false);
      })
      .on('timeout', () => {
        this.log('Warning: Audit service request timeout', 'warning');
        this.log('Continuing with migration run (audit skipped).', 'info');
        resolve(false);
      })
      .once('socket', (socket) => {
        socket.setTimeout(10000);
      })
      .end(JSON.stringify(payload));
  });
}

