  migrationsDir: process.env.MIGRATIONS_DIR || './migrations',
  dryRun: false,
  verbose: false,
};

// Parse command line arguments
program
  .name('migrate')
  .description('Database migration script that reads SQL files and logs them')
  .option('-d, --dir <path>', 'Directory containing migration SQL files', config.migrationsDir)
  .option('-n, --dry-run', 'Preview migrations without executing them', config.dryRun)
  .option('-v, --verbose', 'Enable verbose output', config.verbose)
  .parse(process.argv);

const options = program.opts();

// Validate migrations directory exists
function validateMigrationsDir(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`❌ Error: Migrations directory "${dir}" does not exist.`);
    process.exit(1);
  }
}

// Get list of SQL migration files sorted alphabetically
function getMigrationFiles(directory) {
  try {
    const files = fs.readdirSync(directory);
    const sqlFiles = files
      .filter(file => {
        const ext = path.extname(file).toLowerCase();
        return ext === '.sql';
      })
      .sort((a, b) => a.localeCompare(b)); // Sort alphabetically
    return sqlFiles;
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

// Main migration function
function runMigrations() {
  const dir = options.dir;
  validateMigrationsDir(dir);

  const migrationFiles = getMigrationFiles(dir);

  logDivider();
  console.log(`📂 Migration Files in "${dir}" (${migrationFiles.length} total)`);
  logDivider();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No SQL migration files found.');
    return;
  }

  // Log each migration file
  migrationFiles.forEach((file, index) => {
    const filePath = path.join(dir, file);
    const fileSize = (fs.statSync(filePath).size / 1024).toFixed(2); // Size in KB
    const timestamp = new Date().toISOString();

    console.log(`\n${index + 1}. 📄 ${file}`);
    console.log(`   📍 Path: ${filePath}`);
    console.log(`   📊 Size: ${fileSize} KB`);
    console.log(`   ⏰ Ready to apply at: ${timestamp}`);

    if (config.verbose) {
      // In verbose mode, also print the content preview
      logDivider('─', 40);
      console.log(`   💬 SQL Content Preview:`);
      logDivider('─', 40);
      const content = fs.readFileSync(filePath, 'utf8');
      const lines = content.split('\n').slice(0, 5); // Show first 5 lines
      console.log(lines.join('\n'));
      if (content.split('\n').length > 5) {
        console.log('   ...');
      }
      logDivider('─', 40);
    }
  });

  logDivider();

  if (config.dryRun) {
    console.log('💡 Dry run mode - no migrations were applied.');
  } else {
    console.log('✅ Migration list complete.');
    console.log('   Tip: To actually run these migrations, combine with a database client.');
  }
  logDivider();

  // Return count for programmatic use
  return migrationFiles.length;
}

// Helper function to print a divider line
function logDivider(char = '─', length = 80) {
  console.log(char.repeat(length));
}

// Export for programmatic use
if (module && module.exports) {
  module.exports = {
    runMigrations,
    getMigrationFiles,
    validateMigrationsDir,
  };
}

// Run migrations if this file is executed directly
if (require.main === module) {
  const count = runMigrations();
  process.exit(0);
}

