  } else {
    console.log('✅ Migration list complete.');
    console.log('   Tip: To actually run these migrations, combine with a database client.');
  }
  logDivider();

  // Return count for programmatic use
  return migrationFiles.length;
}

// Export for programmatic use
if (module && module.exports) {
  module.exports = {
    runMigrations,
    getMigrationFiles,
    validateMigrationsDir,
  };
}

// Run migrations if this file is executed directly
if (require.main === module) {
  runMigrations()
