    const migrationsDir = path.join(__dirname, 'migrations');

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error(`Error: Migrations directory "${migrationsDir}" not found.`);
        process.exit(1);
    }

    // Read all files from the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for SQL files (common extensions: .sql, .migration.sql, etc.)
    const sqlFiles = files
        .filter(file => {
            const ext = path.extname(file).toLowerCase();
            return ['.sql', '.migration.sql', '.sql'].includes(ext);
        })
        // Sort files alphabetically to ensure consistent migration order
        .sort();

    if (sqlFiles.length === 0) {
        console.log('No migration files found in the migrations directory.');
        return;
    }

    console.log(`Found ${sqlFiles.length} migration file(s):\n`);

    // Log each migration file it would apply
    sqlFiles.forEach((filename, index) => {
        const fullPath = path.join(migrationsDir, filename);
        const stats = fs.statSync(fullPath);
        const fileSize = (stats.size / 1024).toFixed(2); // Size in KB

        console.log(`${index + 1}. ${filename} (${fileSize} KB)`);
    });

    console.log('');
}

// Run the migrations
try {
    runMigrations();
} catch (error) {
    console.error('Error running migrations:', error.message);
    process.exit(1);
}

