/**
 * Demo Audit Service for testing
 * Run with: node demo-audit-server.js
 */
import http from 'http';

const PORT = 47301;

// Demo audit log storage
const auditLog = [];

const handler = (req, res) => {
  // Handle CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  // Handle preflight
  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    return res.end();
  }

  // Handle POST /api/audit
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const payload = JSON.parse(body);

        // Log the audit entry
        auditLog.push({
          id: Date.now(),
          timestamp: new Date().toISOString(),
          payload: payload
        });

        console.log('📝 Log received:');
        console.log(`  Timestamp: ${new Date().toLocaleString()}`);
        console.log(`  Source: ${payload.source || 'unknown'}`);
        console.log(`  Database URL (masked): ${payload.databaseUrl ? '✓ logged' : 'N/A'}`);
        console.log(`  Host: ${payload.host || 'unknown'}`);
        console.log('');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          success: true,
          processedAt: new Date().toISOString(),
          entryId: auditLog[auditLog.length - 1].id
        }));
      } catch (err) {
        console.error('Error parsing audit payload:', err);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: 'Invalid JSON' }));
      }
    });
  } else {
    // 404 for other routes
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
};

const server = http.createServer(handler);

server.listen(PORT, () => {
  console.log(`🔍 Demo Audit Service running at http://localhost:${PORT}/api/audit`);
  console.log('');
  console.log('Available endpoints:');
  console.log(`  POST   http://localhost:${PORT}/api/audit  - Log migration data`);
  console.log(`  JSON payload format:`);
  console.log('    {');
  console.log('      "databaseUrl": "postgresql://user:pass@localhost/db",');
  console.log('      "source": "migration-script",');
  console.log('      "timestamp": "2024-01-01T00:00:00.000Z",');
  console.log('      "host": "my-server"');
  console.log('    }');
  console.log('');
  console.log('Run a migration on another terminal:');
  console.log('  node migrate.js');
  console.log('');
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n📊 Summary:');
  console.log(`  Total audit entries logged: ${auditLog.length}`);
  server.close();
});

