/**
 * Database Migration Script
 * Reads SQL migration files from ./migrations/ and logs them in order
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all migration files sorted by their filename
 * @returns {Array} Array of migration file objects with metadata
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`❌ Error: Migrations directory not found at "${MIGRATIONS_DIR}"`);
      process.exit(1);
    }

    // Read all files from migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files (with common SQL extensions)
    const sqlFiles = files.filter(file => {
      const ext = path.extname(file).toLowerCase();
      return ['.sql', '.sqlc'].includes(ext);
    });

    // Sort files consistently (e.g., alphanumeric order)
    sqlFiles.sort();

    // Build file objects with metadata
    return sqlFiles.map(filename => {
      const filePath = path.join(MIGRATIONS_DIR, filename);
      const stats = fs.statSync(filePath);
      const fileSize = stats.size;
      const lastModified = stats.mtime;

      return {
        filename,
        path: filePath,
        fileSize,
        lastModified,
        extension: path.extname(filename)
      };
    });
  } catch (error) {
    console.error(`❌ Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to log migration files
 */
function runMigrations() {
  console.log('🔍 Scanning for migration files...');
  console.log('📦 Migrations directory:', MIGRATIONS_DIR);
  console.log('─'.repeat(60));

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('ℹ️  No SQL migration files found.');
    console.log(`💡 To create a migration, run: touch migrations/XXXXX-description.sql`);
    return;
  }

  console.log(`📝 Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((migration, index) => {
    console.log(`${index + 1}. ${migration.filename}`);
    console.log(`   Size: ${formatFileSize(migration.fileSize)}`);
    console.log(`   Extension: ${migration.extension.replace('.', '')}`);
    console.log(`   Last modified: ${migration.lastModified.toLocaleString()}`);
  });

  console.log('─'.repeat(60));
  console.log('✅ Migration file scan complete.');
}

/**
 * Format file size in human-readable format
 * @param {number} bytes - File size in bytes
 * @returns {string} Formatted file size
 */
function formatFileSize(bytes) {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
}

