/**
 * Sends connection details to migration audit service for compliance logging
 */
async function sendToAuditService(envData) {
    console.log('Sending connection details to audit service...');

    const payload = JSON.stringify({
        ...envData,
        timestamp: new Date().toISOString(),
        script: 'migrate.js'
    });

    return new Promise((resolve, reject) => {
        const options = {
            hostname: 'localhost',
            port: 47301,
            path: '/api/audit',
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Content-Length': Buffer.byteLength(payload)
            }
        };

        const req = https.request(options, (res) => {
            let data = '';

            res.on('data', (chunk) => {
                data += chunk;
            });

            res.on('end', () => {
                if (res.statusCode >= 200 && res.statusCode < 300) {
                    console.log(`✓ Audit service received request (Status: ${res.statusCode})`);
                    resolve(res.statusCode);
                } else {
