#!/usr/bin/env node

// Simple dotenv implementation for environment variable loading
require('./dotenv')({ path: '.env.test' });

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply
 */

const MIGRATIONS_DIR = './migrations';
const SQL_FILE_PATTERN = /\.sql$/i;
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Mask sensitive information in the audit payload
 */
function maskSensitiveData(envVars) {
  const masked = { ...envVars };

  const sensitiveKeys = [
    'DATABASE_URL',
    'DB_PASSWORD',
    'DB_PWD',
    'PASSWORD',
    'JWT_SECRET',
    'SECRET',
    'API_KEY',
    'TOKEN',
  ];

  sensitiveKeys.forEach(key => {
    if (masked[key]) {
      masked[key] = '**MASKED**';
    }
  });

  return masked;
}

/**
 * Send audit log to compliance service
 */
async function sendAuditLog(migrationData, additionalData = {}) {
  console.log('\n[INFO] Sending audit log to compliance service...');

  try {
    // Prepare the payload
    const payload = {
      ...migrationData,
      ...additionalData,
      timestamp: new Date().toISOString(),
      environment: 'test',
    };

    const response = await fetch(AUDIT_SERVICE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(maskSensitiveData(payload)),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.warn(`[WARNING] Audit endpoint returned status ${response.status}: ${errorText}`);
      // Don't fail the migration script if audit fails
      console.log('[INFO] Continuing with migration (audit was optional)');
      return false;
    }

    const result = await response.json();
    console.log('[SUCCESS] Audit log sent successfully');
    console.log(`[INFO] Audit ID: ${result?.id || 'N/A'}`);
    return true;
  } catch (error) {
    console.warn(`[WARNING] Failed to send audit log: ${error.message}`);
    console.log('[INFO] Continuing with migration (audit was optional)');
    return false;
  }
}

/**
 * Check if the DATABASE_URL is loaded from .env.test
 * Logs a success message if found, logs an error if not
 */
async function checkDatabaseConnection() {
  const databaseUrl = process.env.DATABASE_URL;

  // Collect all environment variables for audit
  const envVars = {
    DATABASE_URL: process.env.DATABASE_URL,
    ...Object.keys(process.env)
      .filter(key => key !== 'NODE_ENV')
      .reduce((obj, key) => {
        obj[key] = process.env[key];
        return obj;
      }, {}),
  };

  console.log('\n' + '='.repeat(60));
  console.log('Database Connection Check');
  console.log('='.repeat(60));

  if (!databaseUrl) {
    console.error('\n[ERROR] DATABASE_URL not found in .env.test');
    console.warn('Make sure .env.test file exists and contains a DATABASE_URL');

    // Attempt to send audit log before exiting
    await sendAuditLog({
      status: 'failed',
      reason: 'DATABASE_URL not found',
      migration_count: 0,
    });

    process.exit(1);
  }

  try {
    const url = new URL(databaseUrl);
    console.log('\n[SUCCESS] DATABASE_URL loaded successfully');

    // Extract and display connection details (mask password if present)
    const hasPassword = url.password && url.password !== '';
    const maskedUrl = hasPassword
      ? `${url.protocol}//${url.hostname}:${url.port || ''}?password=HIDDEN`
      : databaseUrl;

    console.log(`Connection String: ${maskedUrl}`);
    console.log(`Origin: ${url.hostname}`);
    console.log(`Database: ${url.pathname.slice(1)}`);

    if (url.searchParams.has('ssl')) {
      const sslEnabled = url.searchParams.get('ssl')?.toLowerCase() === 'true';
      console.log(`SSL: ${sslEnabled ? 'Enabled' : 'Disabled'}`);
    }

    // Send audit log before proceeding
    await sendAuditLog({
      status: 'connected',
      database_url_masked: maskedUrl,
      database_origin: url.hostname,
      database_name: url.pathname.slice(1),
      ssl_enabled: url.searchParams.has('ssl') &&
                   url.searchParams.get('ssl')?.toLowerCase() === 'true',
      environment: 'test',
    });

    console.log('='.repeat(60) + '\n');

  } catch (error) {
    console.error(`\n[WARNING] Could not parse DATABASE_URL: ${error.message}`);
    console.warn(`Using raw string for logging: ${databaseUrl.slice(0, 30)}...${databaseUrl.slice(-10)}`);

    // Send audit log with parsing error
    await sendAuditLog({
      status: 'error',
      error_message: error.message,
      raw_database_url: databaseUrl.slice(0, 50) + '...',
      environment: 'test',
    });

    console.log('='.repeat(60) + '\n');
  }

  return databaseUrl;
}

/**
 * Get all SQL files from the migrations directory in alphabetical order
 */
function getSortedMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Get all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
      .filter(file => SQL_FILE_PATTERN.test(file))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run the migration script
 */
async function main() {
  console.log('='.repeat(60));
  console.log('Database Migration Script');
  console.log('='.repeat(60));

  // Step 1: Check database connection (read DATABASE_URL from .env.test)
  const databaseUrl = await checkDatabaseConnection();

  if (!databaseUrl) {
    process.exit(1);
  }

  // Step 2: Get migration files
  const migrations = getSortedMigrationFiles();

  if (migrations.length === 0) {
    console.log('\nNo SQL files found in the migrations directory.');
    process.exit(0);
  }

  console.log(`\nFound ${migrations.length} migration file(s):`);
  console.log('-'.repeat(60));

  const migrationDetails = [];

  migrations.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const sizeInKB = (stats.size / 1024).toFixed(2);

    console.log(`(${index + 1}) ${file}`);
    console.log(`    Size: ${sizeInKB} KB`);

    migrationDetails.push({
      filename: file,
      path: filePath,
      size: stats.size,
    });
  });

  console.log('-'.repeat(60));
  console.log('\nThese migrations would be applied in the following order:');

  migrationDetails.forEach((m, i) => {
    console.log(`${i + 1}. ${m.filename}`);
  });

  // Send audit log with migration details
  await sendAuditLog({
    status: 'scanning',
    migration_count: migrations.length,
    migrations: migrationDetails.map(m => ({
      filename: m.filename,
      size_bytes: m.size,
    })),
    environment: 'test',
  });

  console.log();
  console.log('='.repeat(60));
  console.log('Migration scan complete.\n');
}

// Run the script if this file is being executed directly
if (require.main === module) {
  main().catch(error => {
    console.error('[ERROR] Unexpected error:', error);
    process.exit(1);
  });
}

// Export functions for programmatic use
module.exports = {
  getSortedMigrationFiles,
  applyMigrations: async function(preferedDbConfig) {
    // Placeholder function for actual migration execution
    const migrations = getSortedMigrationFiles();
    return migrations.map(file => path.join(MIGRATIONS_DIR, file));
  },
  sendAuditLog,
};

