#!/usr/bin/env node

const fs = require('fs');
const path = require('path');
const readline = require('readline');

/**
 * Reads SQL files from the ./migrations/ directory and logs each filename in order.
 * This script helps you verify which migrations would be applied to the database.
 */

// ANSI color codes for printing
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  blue: '\x1b[34m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m'
};

// Function to print with color
function printColored(message, color = colors.reset) {
  console.log(`${color}${message}${colors.reset}`);
}

/**
 * Promisified version of fs.readdir to handle async operations
 */
function readdirAsync(dir) {
  return new Promise((resolve, reject) => {
    fs.readdir(dir, { withFileTypes: true }, (err, files) => {
      if (err) {
        reject(err);
      } else {
        resolve(files);
      }
    });
  });
}

/**
 * Filters and sorts migration files
 * @param {string[]} files - Array of file names and dirents
 * @returns {Array} - Sorted array of migration file paths
 */
function getMigrationFiles(files) {
  return files
    .filter(file => file.isFile() && file.name.endsWith('.sql'))
    .map(file => ({
      name: file.name,
      path: path.join(file.parentPath, file.name),
      // Extract version number for ordering (format: YYYYMMDD_HHMMSS_name.sql)
      version: extractVersionNumber(file.name)
    }))
    .sort((a, b) => a.version.localeCompare(b.version))
    .map(file => file.path);
}

/**
 * Extracts version number from filename
 * Assumes format: YYYYMMDD_HHMMSS_description.sql
 quirky or custom versioning
 function to sort files consistently.
 * @param {string} filename - Name of the migration SQL file
 * @returns {string} - Version number (or empty string if format doesn't match)
 */
function extractVersionNumber(filename) {
  // Remove .sql extension
  const nameWithoutExt = filename.replace(/\.sql$/i, '');

  // Match timestamp pattern (YYYYMMDD_HHMMSS)
  const match = nameWithoutExt.match(/^(\d{8}_\d{6})/);

  return match ? match[1] : nameWithoutExt;
}

/**
 * Main function to run the migration
 */
async function runMigration() {
  const migrationsDir = path.join(__dirname, 'migrations');

  try {
    printColored('\n📁 Migration Files Check', colors.cyan);
    printColored('='.repeat(40), colors.blue);

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      printColored(`\n❌ migrations/ directory not found at ${migrationsDir}`, colors.yellow);
      process.exit(1);
    }

    // Get all files in migrations directory
    const dirents = await readdirAsync(migrationsDir);
    const mFiles = getMigrationFiles(dirents);

    // Log results
    if (mFiles.length === 0) {
      printColored('\n📄 No migration files found in ./migrations/', colors.yellow);
    } else {
      printColored(`\n✅ Found ${mFiles.length} migration file(s):\n`, colors.green);

      const migrationNumbers = mFiles.length;

      mFiles.forEach((filePath, index) => {
        const filename = path.basename(filePath);
        const isLastFile = index === mFiles.length - 1;

        if (isLastFile) {
          printColored(`${index + 1}. ${filename}`, colors.blue);
        } else {
          printColored(`${index + 1}. ${filename}`, colors.cyan);
        }
      });
    }

    printColored('\n' + '='.repeat(40), colors.blue);
    printColored('\n💡 Tip: To apply these migrations, connect to your database\n   and execute each SQL file in order.', colors.yellow);
    printColored('='.repeat(40) + '\n', colors.blue);

  } catch (error) {
    printColored(`\n❌ Error reading migration directory: ${error.message}`, colors.yellow);
    process.exit(1);
  }
}

// Run the migration script
runMigration();

-- Create users table
CREATE TABLE IF NOT EXISTS users (
  id SERIAL PRIMARY KEY,
  email VARCHAR(255) UNIQUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

