 * Masks sensitive parts of a database connection string
 * Keeps scheme, host, and ports visible, hides credentials
 * @param {string} str - Connection string
 * @returns {string} - Masked connection string
 */
function maskConnectionString(str) {
  // Replace password:****@host with password:****@host
  return str.replace(/:(?=[^:]+@)/, ':****');
}

/**
